const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");

// Icon rendering
function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

async function main() {
  const {
    FaCog, FaExclamationTriangle, FaProjectDiagram, FaListOl,
    FaDatabase, FaChartBar, FaRocket, FaBullseye, FaCheck,
    FaTimes, FaQuestion, FaArrowRight, FaWrench, FaStar,
    FaLightbulb, FaGlobe, FaLayerGroup, FaBrain
  } = require("react-icons/fa");

  // Color palette - Ocean Gradient + deep technical blue
  const C = {
    navy:      "0A1628",
    darkBlue:  "0F2744",
    midBlue:   "1B3A5C",
    teal:      "0891B2",
    cyan:      "06B6D4",
    lightCyan: "A5F3FC",
    mint:      "2DD4BF",
    white:     "FFFFFF",
    offWhite:  "F0F9FF",
    lightGray: "E2E8F0",
    medGray:   "94A3B8",
    darkGray:  "334155",
    textDark:  "1E293B",
    textMid:   "475569",
    accent:    "F59E0B",
    green:     "10B981",
    red:       "EF4444",
    purple:    "8B5CF6",
  };

  const FONT_HEAD = "Georgia";
  const FONT_BODY = "Calibri";

  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "DiaTool-DPO Research Team";
  pres.title = "DiaTool-DPO: Enhancing Tool-Augmented LLM Dialogue via Direct Preference Optimization";

  const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.2 });
  const makeCardShadow = () => ({ type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.12 });

  // ============================================================
  // SLIDE 1: Title Slide
  // ============================================================
  {
    const slide = pres.addSlide();
    slide.background = { color: C.navy };

    // Decorative top bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal }
    });

    // Subtle geometric accent - large circle
    slide.addShape(pres.shapes.OVAL, {
      x: 7.5, y: -1.5, w: 5, h: 5,
      fill: { color: C.darkBlue, transparency: 60 }
    });
    slide.addShape(pres.shapes.OVAL, {
      x: 8.2, y: 2.5, w: 3, h: 3,
      fill: { color: C.midBlue, transparency: 50 }
    });

    // Title
    slide.addText("DiaTool-DPO", {
      x: 0.8, y: 1.0, w: 8, h: 1.0,
      fontSize: 44, fontFace: FONT_HEAD, color: C.white,
      bold: true, margin: 0
    });

    // Subtitle
    slide.addText("Enhancing Tool-Augmented LLM Dialogue\nvia Direct Preference Optimization", {
      x: 0.8, y: 2.0, w: 7.5, h: 1.0,
      fontSize: 20, fontFace: FONT_BODY, color: C.lightCyan,
      margin: 0, lineSpacingMultiple: 1.3
    });

    // Divider line
    slide.addShape(pres.shapes.LINE, {
      x: 0.8, y: 3.2, w: 2.5, h: 0,
      line: { color: C.teal, width: 2.5 }
    });

    // Tagline
    slide.addText("Automatic preference pair construction via MDP-based\ndialogue state modeling for slot-filling & tool call rejection", {
      x: 0.8, y: 3.5, w: 7.5, h: 0.8,
      fontSize: 14, fontFace: FONT_BODY, color: C.medGray,
      margin: 0, lineSpacingMultiple: 1.4
    });

    // Source reference
    slide.addText("arxiv.org/abs/2504.02882", {
      x: 0.8, y: 4.8, w: 4, h: 0.4,
      fontSize: 11, fontFace: FONT_BODY, color: C.teal,
      margin: 0
    });
  }

  // ============================================================
  // SLIDE 2: Problem & Motivation
  // ============================================================
  {
    const slide = pres.addSlide();
    slide.background = { color: C.offWhite };

    // Top teal bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal }
    });

    // Title
    slide.addText("SFT Alone Fails to Teach Slot-Filling and Tool Rejection", {
      x: 0.7, y: 0.3, w: 8.6, h: 0.6,
      fontSize: 26, fontFace: FONT_HEAD, color: C.textDark,
      bold: true, margin: 0
    });

    // Problem statement
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: 1.1, w: 8.6, h: 0.7,
      fill: { color: C.navy }
    });
    slide.addText("Tool-Augmented LLMs must decide: ask follow-up questions, make tool calls, or reject inappropriate requests. SFT with expert trajectories alone cannot reliably learn these dialogue control skills.", {
      x: 0.9, y: 1.15, w: 8.2, h: 0.6,
      fontSize: 12.5, fontFace: FONT_BODY, color: C.lightCyan,
      margin: 0, valign: "middle"
    });

    // Three failure mode cards
    const failModes = [
      { title: "Missing Follow-ups", desc: "Model skips slot-filling questions when user query lacks required arguments", color: C.red },
      { title: "Hallucinated Tool Calls", desc: "Model invents tool parameters instead of asking the user for missing information", color: C.accent },
      { title: "Failed Rejections", desc: "Model attempts tool calls for out-of-scope requests instead of declining gracefully", color: C.purple },
    ];

    const cardW = 2.67;
    const cardGap = 0.3;
    const startX = 0.7;

    failModes.forEach((fm, i) => {
      const cx = startX + i * (cardW + cardGap);

      // Card background
      slide.addShape(pres.shapes.RECTANGLE, {
        x: cx, y: 2.1, w: cardW, h: 1.95,
        fill: { color: C.white },
        shadow: makeCardShadow()
      });

      // Left accent bar
      slide.addShape(pres.shapes.RECTANGLE, {
        x: cx, y: 2.1, w: 0.06, h: 1.95,
        fill: { color: fm.color }
      });

      // Card title
      slide.addText(fm.title, {
        x: cx + 0.2, y: 2.25, w: cardW - 0.35, h: 0.4,
        fontSize: 14, fontFace: FONT_BODY, color: C.textDark,
        bold: true, margin: 0
      });

      // Card description
      slide.addText(fm.desc, {
        x: cx + 0.2, y: 2.7, w: cardW - 0.35, h: 1.1,
        fontSize: 11.5, fontFace: FONT_BODY, color: C.textMid,
        margin: 0, lineSpacingMultiple: 1.3
      });
    });

    // Bottom insight box
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: 4.3, w: 8.6, h: 0.95,
      fill: { color: C.white },
      shadow: makeCardShadow()
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: 4.3, w: 0.06, h: 0.95,
      fill: { color: C.teal }
    });

    const arrowIcon = await iconToBase64Png(FaArrowRight, "#0891B2", 256);
    slide.addImage({
      data: arrowIcon, x: 0.95, y: 4.5, w: 0.3, h: 0.3
    });

    slide.addText("DiaTool-DPO proposes Direct Preference Optimization with automatically constructed paired trajectories — teaching the model which dialogue flows are correct vs. incorrect without human labeling.", {
      x: 1.4, y: 4.35, w: 7.7, h: 0.85,
      fontSize: 12, fontFace: FONT_BODY, color: C.textDark,
      margin: 0, valign: "middle", lineSpacingMultiple: 1.3
    });
  }

  // ============================================================
  // SLIDE 3: Five-State MDP
  // ============================================================
  {
    const slide = pres.addSlide();
    slide.background = { color: C.offWhite };

    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal }
    });

    slide.addText("Modeling TA-LLM Dialogue as a 5-State MDP", {
      x: 0.7, y: 0.3, w: 8.6, h: 0.6,
      fontSize: 26, fontFace: FONT_HEAD, color: C.textDark,
      bold: true, margin: 0
    });

    // Five state cards in a horizontal flow
    const states = [
      { num: "S1", name: "Initial", desc: "No history.\nReject out-of-scope.", color: C.teal },
      { num: "S2", name: "Tool Selected\nw/o Slots", desc: "Tool identified,\nparams missing.", color: C.cyan },
      { num: "S3", name: "Tool Selected\nw/ Slots", desc: "Tool + all args\ndetermined.", color: C.midBlue },
      { num: "S4", name: "Wait for\nResponse", desc: "Tool call\nexecuted.", color: C.darkBlue },
      { num: "S5", name: "Complete", desc: "Results sent\nto user.", color: C.navy },
    ];

    const stateW = 1.55;
    const stateH = 2.0;
    const stateGap = 0.25;
    const stateStartX = 0.55;
    const stateY = 1.2;

    states.forEach((s, i) => {
      const sx = stateStartX + i * (stateW + stateGap);

      // State card
      slide.addShape(pres.shapes.RECTANGLE, {
        x: sx, y: stateY, w: stateW, h: stateH,
        fill: { color: C.white },
        shadow: makeCardShadow()
      });

      // State number circle
      slide.addShape(pres.shapes.OVAL, {
        x: sx + (stateW - 0.55) / 2, y: stateY + 0.15, w: 0.55, h: 0.55,
        fill: { color: s.color }
      });
      slide.addText(s.num, {
        x: sx + (stateW - 0.55) / 2, y: stateY + 0.15, w: 0.55, h: 0.55,
        fontSize: 14, fontFace: FONT_BODY, color: C.white,
        bold: true, align: "center", valign: "middle", margin: 0
      });

      // State name
      slide.addText(s.name, {
        x: sx + 0.1, y: stateY + 0.8, w: stateW - 0.2, h: 0.55,
        fontSize: 11, fontFace: FONT_BODY, color: C.textDark,
        bold: true, align: "center", valign: "top", margin: 0,
        lineSpacingMultiple: 1.1
      });

      // State description
      slide.addText(s.desc, {
        x: sx + 0.1, y: stateY + 1.35, w: stateW - 0.2, h: 0.55,
        fontSize: 10, fontFace: FONT_BODY, color: C.textMid,
        align: "center", valign: "top", margin: 0,
        lineSpacingMultiple: 1.15
      });

      // Arrow between states (except after last)
      if (i < states.length - 1) {
        slide.addText("\u2192", {
          x: sx + stateW, y: stateY + 0.15, w: stateGap, h: 0.55,
          fontSize: 22, fontFace: FONT_BODY, color: C.teal,
          align: "center", valign: "middle", margin: 0
        });
      }
    });

    // Loop arrow indicator for S2
    slide.addText("\u21BB  Slot-filling loop (N times)", {
      x: 1.85, y: 3.35, w: 2.5, h: 0.35,
      fontSize: 10, fontFace: FONT_BODY, color: C.cyan,
      align: "center", margin: 0, bold: true
    });

    // Self-loop for S1
    slide.addText("\u21BB  Reject (Type 3)", {
      x: 0.55, y: 3.35, w: 1.55, h: 0.35,
      fontSize: 10, fontFace: FONT_BODY, color: C.teal,
      align: "center", margin: 0, bold: true
    });

    // Bottom: trajectory summary
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.55, y: 3.9, w: 8.9, h: 1.35,
      fill: { color: C.navy }
    });

    slide.addText("State Trajectories by Query Type", {
      x: 0.8, y: 4.0, w: 4, h: 0.35,
      fontSize: 14, fontFace: FONT_BODY, color: C.white,
      bold: true, margin: 0
    });

    const trajectories = [
      { type: "Type 1", traj: "S1 → S3 → S4 → S5", label: "All info provided", clr: C.green },
      { type: "Type 2", traj: "S1 → (S2×N) → S3 → S4 → S5", label: "Slot-filling needed", clr: C.accent },
      { type: "Type 3", traj: "S1 → S1", label: "Out-of-scope rejection", clr: C.red },
    ];

    trajectories.forEach((t, i) => {
      const ty = 4.4 + i * 0.28;
      slide.addShape(pres.shapes.OVAL, {
        x: 0.85, y: ty + 0.03, w: 0.16, h: 0.16,
        fill: { color: t.clr }
      });
      slide.addText(`${t.type}:  ${t.traj}`, {
        x: 1.1, y: ty - 0.02, w: 4, h: 0.25,
        fontSize: 11, fontFace: FONT_BODY, color: C.white,
        margin: 0, bold: true
      });
      slide.addText(t.label, {
        x: 5.5, y: ty - 0.02, w: 3, h: 0.25,
        fontSize: 11, fontFace: FONT_BODY, color: C.medGray,
        margin: 0
      });
    });
  }

  // ============================================================
  // SLIDE 4: Three Query Types Table
  // ============================================================
  {
    const slide = pres.addSlide();
    slide.background = { color: C.offWhite };

    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal }
    });

    slide.addText("Three Query Types Define Distinct State Trajectories", {
      x: 0.7, y: 0.3, w: 8.6, h: 0.6,
      fontSize: 26, fontFace: FONT_HEAD, color: C.textDark,
      bold: true, margin: 0
    });

    // Table
    const headerOpts = {
      fill: { color: C.navy },
      color: C.white,
      bold: true,
      fontSize: 13,
      fontFace: FONT_BODY,
      align: "center",
      valign: "middle",
      border: { pt: 0.5, color: C.lightGray }
    };
    const cellOpts = (altRow) => ({
      fill: { color: altRow ? "F8FAFC" : C.white },
      color: C.textDark,
      fontSize: 12,
      fontFace: FONT_BODY,
      valign: "middle",
      border: { pt: 0.5, color: C.lightGray }
    });

    const tableData = [
      [
        { text: "Query Type", options: { ...headerOpts, align: "center" } },
        { text: "State Trajectory", options: { ...headerOpts, align: "center" } },
        { text: "Description", options: { ...headerOpts, align: "center" } },
        { text: "Example", options: { ...headerOpts, align: "center" } },
      ],
      [
        { text: "Type 1\nComplete Query", options: { ...cellOpts(false), bold: true, align: "center" } },
        { text: "1 → 3 → 4 → 5", options: { ...cellOpts(false), fontFace: "Consolas", align: "center", fontSize: 13, color: C.green } },
        { text: "All required arguments present.\nNo slot-filling needed.", options: { ...cellOpts(false), align: "left" } },
        { text: '"Book a flight from NYC to LA on March 15 for 2 passengers"', options: { ...cellOpts(false), italic: true, align: "left", fontSize: 11 } },
      ],
      [
        { text: "Type 2\nIncomplete Query", options: { ...cellOpts(true), bold: true, align: "center" } },
        { text: "1 → (2×N) → 3 → 4 → 5", options: { ...cellOpts(true), fontFace: "Consolas", align: "center", fontSize: 13, color: C.accent } },
