,\n      barGrouping: \"clustered\",\n      chartColors: [C.midBlue, C.teal],\n      chartArea: { fill: { color: C.white }, roundedCorners: true },\n      catAxisLabelColor: C.textDark,\n      catAxisLabelFontSize: 10,\n      valAxisLabelColor: C.medGray,\n      valAxisLabelFontSize: 9,\n      valGridLine: { color: C.lightGray, size: 0.5 },\n      catGridLine: { style: \"none\" },\n      showValue: true,\n      dataLabelPosition: \"outEnd\",\n      dataLabelColor: C.textDark,\n      dataLabelFontSize: 8,\n      showLegend: true,\n      legendPos: \"b\",\n      legendFontSize: 10,\n      valAxisMinVal: 0,\n      valAxisMaxVal: 1.0,\n    });\n\n    // Right side: highlight cards for biggest gains\n    const bigGains = [\n      { metric: \"Slot Accuracy\", before: \"0.639\", after: \"0.917\", gain: \"+43.5%\", color: C.green },\n      { metric: \"Relevance\", before: \"0.826\", after: \"0.913\", gain: \"+10.5%\", color: C.teal },\n      { metric: \"Macro Average\", before: \"0.816\", after: \"0.904\", gain: \"+10.8%\", color: C.cyan },\n    ];\n\n    bigGains.forEach((g, i) => {\n      const cy = 1.3 + i * 1.2;\n\n      slide.addShape(pres.shapes.RECTANGLE, {\n        x: 6.4, y: cy, w: 3.2, h: 1.0,\n        fill: { color: C.white },\n        shadow: makeCardShadow()\n      });\n      slide.addShape(pres.shapes.RECTANGLE, {\n        x: 6.4, y: cy, w: 0.06, h: 1.0,\n        fill: { color: g.color }\n      });\n\n      slide.addText(g.metric, {\n        x: 6.6, y: cy + 0.05, w: 2.8, h: 0.3,\n        fontSize: 12, fontFace: FONT_BODY, color: C.textMid,\n        margin: 0, bold: true\n      });\n\n      // Before → After with gain\n      slide.addText([\n        { text: g.before, options: { fontSize: 20, color: C.medGray, fontFace: FONT_BODY } },\n        { text: \"  →  \", options: { fontSize: 16, color: C.textMid, fontFace: FONT_BODY } },\n        { text: g.after, options: { fontSize: 20, color: C.teal, fontFace: FONT_BODY, bold: true } },\n      ], {\n        x: 6.6, y: cy + 0.35, w: 2.3, h: 0.5,\n        margin: 0, valign: \"middle\"\n      });\n\n      slide.addText(g.gain, {\n        x: 8.85, y: cy + 0.35, w: 0.65, h: 0.5,\n        fontSize: 16, fontFace: FONT_BODY, color: C.green,\n        bold: true, align: \"center\", valign: \"middle\", margin: 0\n      });\n    });\n\n    // Bottom callout\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 0.5, y: 4.85, w: 9.1, h: 0.55,\n      fill: { color: C.navy }\n    });\n    slide.addText(\"Near GPT-4o performance: 94.8% information gathering  |  91% tool call rejection\", {\n      x: 0.7, y: 4.85, w: 8.7, h: 0.55,\n      fontSize: 13, fontFace: FONT_BODY, color: C.lightCyan,\n      margin: 0, valign: \"middle\", align: \"center\"\n    });\n  }\n\n  // ============================================================\n  // SLIDE 8: Key Takeaways\n  // ============================================================\n  {\n    const slide = pres.addSlide();\n    slide.background = { color: C.navy };\n\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal }\n    });\n\n    // Decorative elements\n    slide.addShape(pres.shapes.OVAL, {\n      x: -1.5, y: 3.5, w: 4, h: 4,\n      fill: { color: C.darkBlue, transparency: 60 }\n    });\n\n    slide.addText(\"Key Takeaways\", {\n      x: 0.7, y: 0.3, w: 8.6, h: 0.6,\n      fontSize: 30, fontFace: FONT_HEAD, color: C.white,\n      bold: true, margin: 0\n    });\n\n    slide.addText(\"RL-Based Dialogue Control for Production TA-LLMs\", {\n      x: 0.7, y: 0.85, w: 8.6, h: 0.35,\n      fontSize: 15, fontFace: FONT_BODY, color: C.teal,\n      margin: 0\n    });\n\n    // Five takeaway cards\n    const takeaways = [\n      {\n        title: \"MDP Formulation Enables Systematic Pairing\",\n        desc: \"5 internal states + 3 query types → automatic generation of chosen/rejected trajectory pairs without human annotation.\",\n        color: C.teal,\n      },\n      {\n        title: \"DPO Complements SFT, Not Replaces\",\n        desc: \"DPO-only performs poorly. SFT provides the foundation; DiaTool-DPO adds fine-grained dialogue control on top.\",\n        color: C.cyan,\n      },\n      {\n        title: \"Slot-Filling & Rejection See Largest Gains\",\n        desc: \"LLaMA-3-8B: +43.5% Slot accuracy, +10.5% Relevance — the exact failure modes SFT struggles with most.\",\n        color: C.green,\n      },\n      {\n        title: \"Language-Agnostic Design\",\n        desc: \"Primary experiments in Korean, validated in English. The MDP framework generalizes across languages for broad production applicability.\",\n        color: C.accent,\n      },\n      {\n        title: \"Path to GPT-4o-Level Tool Use on Smaller Models\",\n        desc: \"Open-source 8B models reach near GPT-4o conversational tool-use performance with SFT + DiaTool-DPO.\",\n        color: C.purple,\n      },\n    ];\n\n    const cardStartY = 1.4;\n    const cardH = 0.72;\n    const cardGap = 0.12;\n\n    takeaways.forEach((t, i) => {\n      const cy = cardStartY + i * (cardH + cardGap);\n\n      slide.addShape(pres.shapes.RECTANGLE, {\n        x: 0.7, y: cy, w: 8.6, h: cardH,\n        fill: { color: C.darkBlue },\n      });\n\n      // Left accent\n      slide.addShape(pres.shapes.RECTANGLE, {\n        x: 0.7, y: cy, w: 0.06, h: cardH,\n        fill: { color: t.color }\n      });\n\n      // Number badge\n      slide.addShape(pres.shapes.OVAL, {\n        x: 0.95, y: cy + (cardH - 0.38) / 2, w: 0.38, h: 0.38,\n        fill: { color: t.color }\n      });\n      slide.addText(String(i + 1), {\n        x: 0.95, y: cy + (cardH - 0.38) / 2, w: 0.38, h: 0.38,\n        fontSize: 13, fontFace: FONT_BODY, color: C.white,\n        bold: true, align: \"center\", valign: \"middle\", margin: 0\n      });\n\n      // Title\n      slide.addText(t.title, {\n        x: 1.5, y: cy + 0.06, w: 7.6, h: 0.28,\n        fontSize: 14, fontFace: FONT_BODY, color: C.white,\n        bold: true, margin: 0\n      });\n\n      // Description\n      slide.addText(t.desc, {\n        x: 1.5, y: cy + 0.34, w: 7.6, h: 0.32,\n        fontSize: 11, fontFace: FONT_BODY, color: C.medGray,\n        margin: 0, lineSpacingMultiple: 1.2\n      });\n    });\n\n    // Source bar\n    slide.addText(\"Source: arxiv.org/abs/2504.02882  |  DiaTool-DPO: Multi-Turn Direct Preference Optimization for Tool-Augmented LLMs\", {\n      x: 0.7, y: 5.15, w: 8.6, h: 0.3,\n      fontSize: 10, fontFace: FONT_BODY, color: C.medGray,\n      margin: 0, align: \"center\"\n    });\n  }\n\n  // Write file\n  await pres.writeFile({ fileName: \"/app/output/final_deck.pptx\" });\n  console.log(\"Presentation saved to /app/output/final_deck.pptx\");\n}\n\nmain().catch(err => { console.error(err); process.exit(1); });\n", "numLines": 983, "startLine": 1, "totalLines": 983}}

