    slide.addText("These three trajectory patterns form the basis for automatic preference pair construction \u2014 each type generates its own set of chosen (correct) and rejected (incorrect) dialogue flows for DPO training.", {
      x: 1.25, y: 4.2, w: 8.0, h: 0.8,
      fontSize: 12, fontFace: FONT_BODY, color: C.textDark,
      margin: 0, valign: "middle", lineSpacingMultiple: 1.3
