      valign: "middle",
      align: "center",
      border: { pt: 0.5, color: C.lightGray }
    });

    const dsTable = [
      [
        { text: "Query", options: hOpts },
        { text: "Chosen Trajectory", options: hOpts },
        { text: "Rejected Trajectory", options: hOpts },
        { text: "Learning Lesson", options: hOpts },
        { text: "Count", options: hOpts },
        { text: "Difficulty", options: hOpts },
      ],
      [
        { text: "Type 1", options: { ...cOpts(false), bold: true, color: C.green } },
        { text: "1\u21923\u21924\u21925", options: { ...cOpts(false), fontFace: "Consolas", fontSize: 9.5 } },
        { text: "1\u21922\u21923\u21924\u21925", options: { ...cOpts(false), fontFace: "Consolas", fontSize: 9.5 } },
