        { text: "2,089", options: cOpts(false) },
        { text: "Easy", options: { ...cOpts(false), color: C.green } },
      ],
      [
        { text: "Type 1", options: { ...cOpts(true), bold: true, color: C.green } },
        { text: "1\u21923\u21924\u21925", options: { ...cOpts(true), fontFace: "Consolas", fontSize: 9.5 } },
        { text: "1\u2192(2\u00d7N)\u21923\u21924\u21925", options: { ...cOpts(true), fontFace: "Consolas", fontSize: 9.5 } },
        { text: "Prevent redundant\nslot-filling", options: { ...cOpts(true), align: "left", fontSize: 9.5 } },
        { text: "3,092", options: cOpts(true) },
        { text: "Hard", options: { ...cOpts(true), color: C.accent } },
      ],
      [
        { text: "Type 1", options: { ...cOpts(false), bold: true, color: C.green } },
        { text: "1\u21923\u21924\u21925", options: { ...cOpts(false), fontFace: "Consolas", fontSize: 9.5 } },
