: 0.85, w: 8.6, h: 0.35,", "-      fontSize: 15, fontFace: FONT_BODY, color: C.teal,", "+      x: 0.7, y: 0.72, w: 8.6, h: 0.3,", "+      fontSize: 14, fontFace: FONT_BODY, color: C.teal,", "       margin: 0", "     });", " ", "-    // Five takeaway cards", "     const takeaways = [", "       {", "         title: "MDP Formulation Enables Systematic Pairing",", "-        desc: "5 internal states + 3 query types → automatic generation of chosen/rejected trajectory pairs without human annotation.",", "+        desc: "5 internal states + 3 query types \u2192 automatic chosen/rejected trajectory pairs without human annotation.",", "         color: C.teal,", "       },", "       {", "         title: "DPO Complements SFT, Not Replaces",", "-        desc: "DPO-only performs poorly. SFT provides the foundation; DiaTool-DPO adds fine-grained dialogue control on top.",", "+        desc: "DPO-only performs poorly. SFT provides the foundation; DiaTool-DPO adds fine-grained dialogue control.",", "         color: C.cyan,", "       },", "       {", "         title: "Slot-Filling & Rejection See Largest Gains",", "-        desc: "LLaMA-3-8B: +43.5% Slot accuracy, +10.5% Relevance — the exact failure modes SFT struggles with most.",", "+        desc: "LLaMA-3-8B: +43.5% Slot accuracy, +10.5% Relevance \u2014 the exact failure modes SFT struggles with.",", "         color: C.green,", "       },", "       {", "         title: "Language-Agnostic Design",", "-        desc: "Primary experiments in Korean, validated in English. The MDP framework generalizes across languages for broad production applicability.",", "+        desc: "Primary experiments in Korean, validated in English. MDP framework generalizes for broad production use.",", "         color: C.accent,", "       },", "       {"]}, {"oldStart": 922, "oldLines": 9, "newStart": 891, "newLines": 9, "lines": ["       },", "     ];", " ", "-    const cardStartY = 1.4;", "+    const cardStartY = 1.15;", "     const cardH = 0.72;", "-  