    lightCyan: "A5F3FC",
    mint:      "2DD4BF",
    white:     "FFFFFF",
    offWhite:  "F0F9FF",
    lightGray: "E2E8F0",
    medGray:   "94A3B8",
    darkGray:  "334155",
    textDark:  "1E293B",
    textMid:   "475569",
    accent:    "F59E0B",
    green:     "10B981",
    red:       "EF4444",
    purple:    "8B5CF6",
  };

  const FONT_HEAD = "Georgia";
