      [
        { text: "Type 3\nOut-of-Scope", options: { ...cellOpts(false), bold: true, align: "center" } },
        { text: "1 \u2192 1", options: { ...cellOpts(false), fontFace: "Consolas", align: "center", fontSize: 13, color: C.red } },
