      },
    ];

    const cardStartY = 1.15;
    const cardH = 0.72;
    const cardGap = 0.15;

    takeaways.forEach((t, i) => {
      const cy = cardStartY + i * (cardH + cardGap);

      slide.addShape(pres.shapes.RECTANGLE, {
        x: 0.7, y: cy, w: 8.6, h: cardH,
