      });

      slide.addShape(pres.shapes.OVAL, {
        x: 0.95, y: cy + (cardH - 0.36) / 2, w: 0.36, h: 0.36,
        fill: { color: t.color }
      });
      slide.addText(String(i + 1), {
        x: 0.95, y: cy + (cardH - 0.36) / 2, w: 0.36, h: 0.36,
